mapper.select:
WITH RECURSIVE sub AS (SELECT id, parent_id FROM navigation_menu WHERE id = #{id}
UNION ALL
SELECT p.id, p.parent_id FROM navigation_menu AS p INNER JOIN sub AS s ON p.id = s.parent_id) SELECT id FROM sub

SELECT nm.id, nm.name, nm.depth, nm.type, nm.image_url, nm.parent_id, nm.target_id, nm.sort_weight, nm.created_time, nm.is_enable AS enable, pnm.name AS parentName
FROM navigation_menu AS nm LEFT JOIN navigation_menu AS pnm ON nm.parent_id = pnm.id
WHERE nm.is_deleted = 0 AND nm.id = #{menuId}
